const cw_color PCOL[NP] = {
  { 0.93f, 0.28f, 0.30f, 1 }, { 0.25f, 0.55f, 0.95f, 1 }, { 0.30f, 0.80f, 0.45f, 1 }, { 0.98f, 0.78f, 0.22f, 1 },
};
const char *PNAME[NP] = { "Ruby", "Sky", "Mint", "Sun" };

uint32_t hash_u32(uint32_t h, uint32_t v) {
  for (int i = 0; i < 4; i++) h = (h ^ ((v >> (8 * i)) & 255)) * 16777619u;
  return h;
}

cw_color col_mix(cw_color a, cw_color b, float t) {
  return (cw_color){ flerp(a.r, b.r, t), flerp(a.g, b.g, t), flerp(a.b, b.b, t), flerp(a.a, b.a, t) };
}
cw_color col_a(cw_color c, float a) { c.a = a; return c; }
float ease_out(float t) { t = fclampf(t, 0, 1); return 1 - (1 - t) * (1 - t) * (1 - t); }
float ease_back(float t) {
  t = fclampf(t, 0, 1);
  float c = 1.70158f, u = t - 1;
  return 1 + (c + 1) * u * u * u + c * u * u;
}

/* ── sound ──────────────────────────────────────────────────────────── */

static cw_sound S[SFX_N];
static cw_sound music_hub, music_game;
static cw_voice music_voice;
static int music_now;
static uint32_t noise_state = 12345;
static float noise(void) {
  noise_state = noise_state * 1664525u + 1013904223u;
  return (float)(noise_state >> 8) / 8388608.0f - 1.0f;
}

enum { RATE = 44100 };
static float pcm_buf[RATE * 9];

static cw_sound make(float secs, float hz0, float hz1, float gain, int wave, float noise_mix) {
  int n = (int)(secs * RATE);
  double ph = 0;
  for (int i = 0; i < n; i++) {
    float t = (float)i / (float)n;
    float hz = hz0 + (hz1 - hz0) * t;
    ph += TAU * hz / RATE;
    float s = wave == 0 ? sinf((float)ph) : wave == 1 ? (sinf((float)ph) > 0 ? 1.0f : -1.0f) * 0.5f : (float)(fmod(ph / TAU, 1.0) * 2 - 1) * 0.6f;
    s = s * (1 - noise_mix) + noise() * noise_mix;
    float env = (1 - t) * (1 - t);
    if (i < 80) env *= (float)i / 80.0f;
    pcm_buf[i] = s * gain * env;
  }
  return cw_sound_from_pcm(pcm_buf, n, 1, RATE, NULL);
}

/* a crowd's ooh: a dozen voices on slightly different pitches singing an oo that falls, with breath in it; it swells
 * in and fades out (no hard edge) */
static cw_sound make_crowd(float secs) {
  int n = (int)(secs * RATE);
  memset(pcm_buf, 0, sizeof(float) * (size_t)n);
  for (int v = 0; v < 12; v++) {
    float hz0 = 150 + (float)((v * 37) % 160), drop = 0.72f + 0.04f * (float)(v % 3);
    double ph = (double)v * 0.7;
    for (int i = 0; i < n; i++) {
      float t = (float)i / (float)n;
      ph += TAU * hz0 * (1 - (1 - drop) * t) / RATE;
      float x = sinf((float)ph) + 0.45f * sinf((float)ph * 2) + 0.12f * sinf((float)ph * 3); /* a round oo */
      pcm_buf[i] += x * 0.045f;
    }
  }
  float lp = 0;
  for (int i = 0; i < n; i++) {
    float t = (float)i / (float)n;
    lp += (noise() - lp) * 0.08f; /* breath: soft low noise */
    float env = t < 0.18f ? t / 0.18f : (1 - t) / 0.82f;
    pcm_buf[i] = (pcm_buf[i] + lp * 0.35f) * env * env * 0.9f;
  }
  return cw_sound_from_pcm(pcm_buf, n, 1, RATE, NULL);
}

/* a looped bar pattern: notes are scale degrees, 0 = rest */
static cw_sound make_music(float bpm, const int *notes, int count, float root, int bars, float gain, bool bass) {
  static const float scale[8] = { 0, 2, 4, 7, 9, 12, 14, 16 };
  float step = 60.0f / bpm / 2; /* eighth notes */
  int n = (int)(step * count * bars * RATE);
  if (n > RATE * 9) n = RATE * 9;
  memset(pcm_buf, 0, sizeof(float) * (size_t)n);
  for (int k = 0; k < count * bars; k++) {
    int deg = notes[k % count];
    int s0 = (int)(k * step * RATE), len = (int)(step * 1.6f * RATE);
    if (deg > 0) {
      float hz = root * powf(2.0f, scale[deg - 1] / 12.0f);
      double ph = 0;
      for (int i = 0; i < len && s0 + i < n; i++) {
        float t = (float)i / (float)len;
        ph += TAU * hz / RATE;
        float env = (1 - t) * (1 - t) * (i < 60 ? (float)i / 60.0f : 1);
        pcm_buf[s0 + i] += (sinf((float)ph) + 0.35f * sinf((float)ph * 2)) * gain * env;
      }
    }
    if (bass && k % 4 == 0) {
      double ph = 0;
      int bl = (int)(step * 3.5f * RATE);
      for (int i = 0; i < bl && s0 + i < n; i++) {
        float t = (float)i / (float)bl;
        ph += TAU * root * 0.5f / RATE;
        pcm_buf[s0 + i] += sinf((float)ph) * gain * 1.2f * (1 - t) * (i < 60 ? (float)i / 60.0f : 1);
      }
    }
    if (k % 2 == 1) { /* a soft tick on the off beat */
      for (int i = 0; i < 900 && s0 + i < n; i++) pcm_buf[s0 + i] += noise() * gain * 0.18f * (1 - (float)i / 900.0f);
    }
  }
  return cw_sound_from_pcm(pcm_buf, n, 1, RATE, NULL);
}

extern cw_bus pp_music_bus(void);
extern cw_bus pp_sfx_bus(void);

void sfx_init(void) {
  S[SFX_BLIP] = make(0.05f, 700, 700, 0.25f, 0, 0);
  S[SFX_SELECT] = make(0.14f, 520, 1040, 0.3f, 0, 0);
  S[SFX_BACK] = make(0.14f, 520, 260, 0.3f, 0, 0);
  S[SFX_COIN] = make(0.18f, 988, 1480, 0.3f, 1, 0);
  S[SFX_HIT] = make(0.14f, 220, 90, 0.5f, 2, 0.35f);
  S[SFX_BOOM] = make(0.9f, 110, 30, 0.9f, 0, 0.55f);
  S[SFX_JUMP] = make(0.16f, 300, 640, 0.3f, 1, 0);
  S[SFX_WIN] = make(0.6f, 520, 1560, 0.35f, 0, 0);
  S[SFX_LOSE] = make(0.6f, 400, 120, 0.4f, 2, 0);
  S[SFX_TICK] = make(0.07f, 880, 880, 0.35f, 0, 0);
  S[SFX_GO] = make(0.4f, 880, 1320, 0.45f, 1, 0);
  S[SFX_SPLASH] = make(0.4f, 300, 200, 0.5f, 0, 0.9f);
  S[SFX_BOUNCE] = make(0.1f, 200, 500, 0.3f, 0, 0);
  S[SFX_BUZZ] = make(0.25f, 140, 120, 0.35f, 2, 0);
  S[SFX_POP] = make(0.08f, 900, 300, 0.35f, 0, 0.2f);
  S[SFX_OOH] = make_crowd(1.3f);
  static const float notes[8] = { 261.63f, 293.66f, 329.63f, 392.0f, 440.0f, 523.25f, 587.33f, 659.25f };
  for (int i = 0; i < 8; i++) S[SFX_NOTE0 + i] = make(0.35f, notes[i], notes[i], 0.35f, 0, 0);
  static const int hub[16] = { 1, 0, 3, 0, 5, 0, 3, 0, 4, 0, 6, 0, 5, 0, 3, 2 };
  static const int game[16] = { 1, 3, 5, 3, 1, 4, 6, 4, 2, 4, 6, 4, 3, 5, 7, 5 };
  music_hub = make_music(100, hub, 16, 261.63f, 2, 0.10f, true);
  music_game = make_music(138, game, 16, 293.66f, 2, 0.085f, true);
}

#ifdef PP_AUTOPILOT
int pp_batch_active(void);
#endif
void sfx(int id, float vol, float pitch) {
  if (id < 0 || id >= SFX_N) return;
#ifdef PP_AUTOPILOT
  if (pp_batch_active()) return; /* a balance run plays no sound */
#endif
  cw_audio_play(S[id], &(cw_play_desc){ .bus = pp_sfx_bus(), .volume = vol > 0 ? vol : 1, .pitch = pitch > 0 ? pitch : 1 });
}
void sfx_music_stop(void) {
  if (cw_voice_is_playing(music_voice)) cw_voice_stop(music_voice, 0.3f);
  music_now = 0;
}
void sfx_music(int which) {
  if (which == music_now && cw_voice_is_playing(music_voice)) return;
  sfx_music_stop();
  if (which == 0) return;
  music_voice = cw_audio_play(which == 1 ? music_hub : music_game, &(cw_play_desc){ .bus = pp_music_bus(), .loop = true });
  music_now = which;
}

/* ── particles and popups ───────────────────────────────────────────── */

typedef struct { cw_vec2 p, v; float life, max, size, r1; cw_color c; int kind; } part;
typedef struct { cw_vec2 p; float life; char s[24]; cw_color c; float size; } pop;
#define NPART 768
#define NPOP 24
static part P[NPART];
static pop POP[NPOP];
static int part_next;
static float fx_rng_state = 1;
bool pp_rumble_off;
int32_t pp_rumble_sent[NP];
static struct { int until[NP]; float low[NP], high[NP]; int clock; } RB;
void pp_rumble_tick(void) { RB.clock++; }
void pp_rumble(const mg_ctx *c, int p, float low, float high, int ms) {
  if (pp_rumble_off || p < 0 || p >= NP || !c->human[p] || ms <= 0) return;
  int left = (RB.until[p] - RB.clock) * 1000 / 60;
  if (left > 0) {
    if (low <= RB.low[p] && high <= RB.high[p] && ms <= left) return;
    low = fmaxf(low, RB.low[p]), high = fmaxf(high, RB.high[p]), ms = ms > left ? ms : left;
  }
  low = fminf(fmaxf(low, 0), 1), high = fminf(fmaxf(high, 0), 1);
  RB.low[p] = low, RB.high[p] = high, RB.until[p] = RB.clock + (ms * 60 + 999) / 1000;
  pp_rumble_sent[p]++;
  cw_input_rumble(p, low, high, ms);
}
void pp_rumble_stop(void) {
  for (int p = 0; p < NP; p++) if (RB.until[p] > RB.clock) cw_input_rumble_stop(p), RB.until[p] = 0;
}

/* the shake check (cam.offset): on the frames (2D stage) and ticks (3D camera) within half a second of an impact (any
 * hit-stop, a blast arena step), the stage as drawn against the centred stage and the 3D camera as drawn against where
 * the game frames it. cam.offset: those samples, the ones off by over 0.1 mm (3D) or 0.0001 stage pixels (2D), and the
 * largest offset (in units of 0.0001). Nothing moves the view on an impact: [n, 0, 0]. */
int32_t cam_offset_dbg[3];
static int impacts, seen2d, seen3d, win2d, win3d;
void fx_impact(void) { impacts++; }
static void offset_note(int *win, int *seen, float off) {
  if (impacts != *seen) *seen = impacts, *win = 30;
  if (*win <= 0) return;
  (*win)--;
  cam_offset_dbg[0]++;
  if (off > 1e-4f) cam_offset_dbg[1]++;
  if ((int32_t)(off * 1e4f) > cam_offset_dbg[2]) cam_offset_dbg[2] = (int32_t)(off * 1e4f);
}
void cam_offset_3d(cw_node cam, float px, float py, float pz) {
  const t3_mat4 *m = cw_node3d_global_transform(cam);
  if (!m) return;
  float dx = m->e[12] - px, dy = m->e[13] - py, dz = m->e[14] - pz;
  offset_note(&win3d, &seen3d, sqrtf(dx * dx + dy * dy + dz * dz));
}
static int hitstop;
void fx_hitstop(int ticks) { fx_impact(); if (ticks > 10) ticks = 10; if (ticks > hitstop) hitstop = ticks; }
int fx_hitstop_take(void) { int n = hitstop; hitstop = 0; return n; }
static int slowmo;
void fx_slowmo(int ticks) {
#ifdef PP_AUTOPILOT
  static int off = -1; /* PP_NO_SLOWMO=1: no fail moments (the check that they change no result) */
  if (off < 0) off = getenv("PP_NO_SLOWMO") != NULL;
  if (off) return;
#endif
  fx_impact();
  if (ticks > 60) ticks = 60;
  if (ticks > slowmo) slowmo = ticks;
}
int fx_slowmo_take(void) { int n = slowmo; slowmo = 0; return n; }
cw_vec2 (*fx_map)(cw_vec2 stage_point);
bool pp_set_on;

static float frand(void) {
  fx_rng_state = fx_rng_state * 16807.0f;
  fx_rng_state = fmodf(fx_rng_state, 2147483647.0f);
  return fx_rng_state / 2147483647.0f;
}

void fx_reset(void) {
  memset(P, 0, sizeof P);
  memset(POP, 0, sizeof POP);
  hitstop = 0;
  slowmo = 0;
  fx_rng_state = 7;
}
static part *np(void) { part *p = &P[part_next++ % NPART]; memset(p, 0, sizeof *p); return p; }
void fx_burst(cw_vec2 pos, int n, cw_color c, float speed, float life, float size) {
  if (fx_map) pos = fx_map(pos);
  for (int i = 0; i < n; i++) {
    part *p = np();
    float a = frand() * TAU, s = speed * (0.3f + frand() * 0.7f);
    p->p = pos;
    p->v = cw_v2(cosf(a) * s, sinf(a) * s);
    p->life = p->max = life * (0.6f + frand() * 0.4f);
    p->size = size * (0.5f + frand() * 0.8f);
    p->c = c;
    p->kind = 0;
  }
}
void fx_ring(cw_vec2 pos, float r0, float r1, float life, cw_color c) {
  if (fx_map) pos = fx_map(pos);
  part *p = np();
  p->p = pos; p->size = r0; p->r1 = r1; p->life = p->max = life; p->c = c; p->kind = 1;
}
void fx_confetti(cw_rect a, int n) {
  for (int i = 0; i < n; i++) {
    part *p = np();
    p->p = cw_v2(a.x + frand() * a.w, a.y);
    p->v = cw_v2((frand() - 0.5f) * 120, 80 + frand() * 140);
    p->life = p->max = 2.5f + frand() * 1.5f;
    p->size = 6 + frand() * 6;
    p->c = PCOL[(int)(frand() * 3.99f)];
    p->kind = 2;
    p->r1 = frand() * TAU;
  }
}
void fx_text(cw_vec2 pos, const char *s, cw_color c, float size) {
  if (fx_map) pos = fx_map(pos);
  static int next;
  pop *o = &POP[next++ % NPOP];
  o->p = pos; o->life = 1.0f; o->c = c; o->size = size;
  snprintf(o->s, sizeof o->s, "%s", s);
}
void fx_update(float dt) {
  for (int i = 0; i < NPART; i++) {
    part *p = &P[i];
    if (p->life <= 0) continue;
    p->life -= dt;
    if (p->kind == 0) { p->p = cw_v2_add(p->p, cw_v2_scale(p->v, dt)); p->v.y += 260 * dt; p->v = cw_v2_scale(p->v, 1 - 1.5f * dt); }
    else if (p->kind == 2) { p->p = cw_v2_add(p->p, cw_v2_scale(p->v, dt)); p->v.x += sinf(p->r1 + p->life * 3) * 40 * dt; }
  }
  for (int i = 0; i < NPOP; i++) if (POP[i].life > 0) { POP[i].life -= dt; POP[i].p.y -= 40 * dt; }
}
void fx_draw(void) {
  for (int i = 0; i < NPART; i++) {
    part *p = &P[i];
    if (p->life <= 0) continue;
    float t = p->life / p->max;
    cw_color c = p->c;
    if (p->kind == 0) { c.a *= t; cw_r2d_circle(p->p, p->size * (0.4f + 0.6f * t), 10, c); }
    else if (p->kind == 1) { float r = flerp(p->r1, p->size, t); c.a *= t; cw_r2d_circle_lines(p->p, r, 4 + 6 * t, 28, c); }
    else { c.a *= fminf(1, t * 3); cw_r2d_rect(cw_rect_make(p->p.x, p->p.y, p->size, p->size * 0.6f), c); }
  }
  for (int i = 0; i < NPOP; i++) {
    if (POP[i].life <= 0) continue;
    cw_color c = POP[i].c;
    c.a = fminf(1, POP[i].life * 2);
    ui_text(POP[i].s, POP[i].p, POP[i].size * (1 + 0.3f * (1 - POP[i].life)), c, CW_ALIGN_CENTER);
  }
}

/* ── drawing ────────────────────────────────────────────────────────── */

cw_rect stage_rect(void) {
  cw_vec2 cv = cw_r2d_canvas_size();
  float k = fminf(cv.x / STAGE_W, cv.y / STAGE_H);
  float w = STAGE_W * k, h = STAGE_H * k;
  return cw_rect_make((cv.x - w) * 0.5f, (cv.y - h) * 0.5f, w, h);
}
void stage_begin(void) {
  cw_rect r = stage_rect();
  float k = r.w / STAGE_W; /* the stage stands still: a hit is felt in the pad (pp_rumble), never in the picture */
  cw_xform2d m = cw_xform2d_trs(cw_v2(r.x, r.y), 0, cw_v2(k, r.h / STAGE_H));
  cw_r2d_set_transform(&m);
  offset_note(&win2d, &seen2d, hypotf(m.tx - r.x, m.ty - r.y) / k);
}
void stage_end(void) {
  cw_xform2d m = cw_xform2d_identity();
  cw_r2d_set_transform(&m);
}

static cw_font pp_font(void) {
  static cw_font f;
  static bool tried;
  if (!tried) { tried = true; f = cw_font_load("fonts/LilitaOne-Regular.ttf", NULL); }
  return f.id ? f : cw_ui_font_sans();
}
float ui_text_w(const char *s, float size) {
  return cw_font_measure(pp_font(), s, &(cw_text_style){ .size = size }).width;
}
void ui_text(const char *s, cw_vec2 p, float size, cw_color c, cw_text_align al) {
  float w = ui_text_w(s, size);
  if (al == CW_ALIGN_CENTER) p.x -= w * 0.5f;
  else if (al == CW_ALIGN_RIGHT) p.x -= w;
  cw_r2d_text(pp_font(), s, p, &(cw_text_style){ .size = size, .color = c, .outline_width = size * 0.07f, .outline_color = cw_rgba(0.05f, 0.04f, 0.1f, c.a) });
}
/* Text size (cartwheel/render2d.h): the player's text scale grows every size here; layouts read these to make room */
float ui_grow(float size) { return cw_text_drawn_size(pp_font(), size) / size; }
float ui_line_h(float size) { return cw_font_measure(pp_font(), "Ag", &(cw_text_style){ .size = size }).height; }
float ui_wrap_h(const char *s, float w, float size) { return cw_font_measure(pp_font(), s, &(cw_text_style){ .size = size, .wrap_width = w }).height; }
/* text over something it labels (a blob, a tile): p.y is where its top sits at 100%; larger text grows upward, its foot stays */
void ui_text_up(const char *s, cw_vec2 p, float size, cw_color c, cw_text_align al) {
  float h = ui_line_h(size);
  ui_text(s, cw_v2(p.x, p.y + h / ui_grow(size) - h), size, c, al);
}
cw_vec2 ui_prompt_up(const char *s, int player, cw_vec2 p, float size, cw_color c, cw_text_align al) {
  float h = ui_prompt_size(s, player, size).y;
  return ui_prompt(s, player, cw_v2(p.x, p.y + h / ui_grow(size) - h), size, c, al);
}
/* the player strip across the top of play: chips as tall as their two lines draw, the clock's pill under them */
float ui_chip_h(void) { return fmaxf(58, 3 + 24 * ui_grow(22) + 31 * ui_grow(26)); }
float ui_clock_y(void) { return 10 + ui_chip_h() + 8; }
float ui_clock_h(void) { return 40 * ui_grow(34); }
/* how far the strip and the clock reach below where they end at 100% (0 then): a game's own top lines move down by it */
bool pp_clock_on = true;
float ui_hud_shift(void) { return pp_clock_on ? ui_clock_y() + ui_clock_h() - 116 : 10 + ui_chip_h() - 68; }
float ui_grew(float size) { float h = ui_line_h(size); return h - h / ui_grow(size); }
void ui_text_wrap(const char *s, cw_rect r, float size, cw_color c, cw_text_align al) {
  float x = r.x;
  if (al == CW_ALIGN_CENTER) x = r.x + r.w * 0.5f;
  else if (al == CW_ALIGN_RIGHT) x = r.x + r.w;
  cw_r2d_text(pp_font(), s, cw_v2(r.x, r.y), &(cw_text_style){ .size = size, .color = c, .wrap_width = r.w, .align = al, .outline_width = size * 0.05f, .outline_color = cw_rgba(0.05f, 0.04f, 0.1f, c.a) });
  (void)x;
}
void ui_panel(cw_rect r, cw_color fill, cw_color edge) {
  cw_r2d_round_rect(cw_rect_make(r.x + 3, r.y + 6, r.w, r.h), 16, 8, cw_rgba(0, 0, 0, 0.3f * fill.a));
  cw_r2d_round_rect(r, 16, 8, fill);
  if (edge.a > 0) cw_r2d_round_rect_lines(r, 16, 3, 8, edge);
}
void ui_pill(cw_rect r, cw_color c) { cw_r2d_round_rect(r, r.h * 0.5f, 8, c); }
void ui_bar(cw_rect r, float f, cw_color c) {
  ui_pill(r, cw_rgba(0, 0, 0, 0.45f));
  f = fclampf(f, 0, 1);
  if (f > 0.02f) ui_pill(cw_rect_make(r.x + 2, r.y + 2, (r.w - 4) * f, r.h - 4), c);
}
cw_vec2 ui_prompt(const char *s, int player, cw_vec2 p, float size, cw_color c, cw_text_align al) {
  return cw_prompt_text(pp_font(), s, player, p, size, c, al);
}
cw_vec2 ui_prompt_size(const char *s, int player, float size) { return cw_prompt_text_size(pp_font(), s, player, size); }
/* a quad with a vertical colour gradient (smooth, unlike stacked bands) */
void ui_grad(cw_rect r, cw_color top, cw_color bot) {
  cw_vertex2d v[4] = { { cw_v2(r.x, r.y), cw_v2(0, 0), top }, { cw_v2(r.x + r.w, r.y), cw_v2(1, 0), top }, { cw_v2(r.x + r.w, r.y + r.h), cw_v2(1, 1), bot }, { cw_v2(r.x, r.y + r.h), cw_v2(0, 1), bot } };
  static const uint32_t idx[6] = { 0, 1, 2, 0, 2, 3 };
  cw_r2d_triangles((cw_texture){ 0 }, v, 4, idx, 6);
}
void ui_grad_h(cw_rect r, cw_color left, cw_color right) {
  cw_vertex2d v[4] = { { cw_v2(r.x, r.y), cw_v2(0, 0), left }, { cw_v2(r.x + r.w, r.y), cw_v2(1, 0), right }, { cw_v2(r.x + r.w, r.y + r.h), cw_v2(1, 1), right }, { cw_v2(r.x, r.y + r.h), cw_v2(0, 1), left } };
  static const uint32_t idx[6] = { 0, 1, 2, 0, 2, 3 };
  cw_r2d_triangles((cw_texture){ 0 }, v, 4, idx, 6);
}
/* dark corners: four soft edge strips over the whole stage */
void ui_vignette(float k) {
  cw_color d = cw_rgba(0, 0, 0, 0.5f * k), z = cw_rgba(0, 0, 0, 0);
  ui_grad(cw_rect_make(0, 0, STAGE_W, 150), d, z);
  ui_grad(cw_rect_make(0, STAGE_H - 170, STAGE_W, 170), z, d);
  ui_grad_h(cw_rect_make(0, 0, 220, STAGE_H), d, z);
  ui_grad_h(cw_rect_make(STAGE_W - 220, 0, 220, STAGE_H), z, d);
}
/* a scrolling tiled ridge line: far layers scroll slower. y is the bottom edge */
void bg_ridge(const char *name, float scroll, float y_bottom, float h, cw_color tint) {
  float w = h * 4;                       /* the baked strip is 1024 x 256 */
  float x0 = -fmodf(scroll, w);
  if (x0 > 0) x0 -= w;
  for (float x = x0; x < STAGE_W; x += w) art_draw_ex(name, cw_v2(x, y_bottom), cw_v2(w + 1, h), cw_v2(0, 1), 0, tint, false, false);
}
void bg_clouds(float t, float y, float scale, float alpha) {
  for (int i = 0; i < 5; i++) {
    float x = fmodf((float)i * 330.0f + t * (6 + (float)(i % 3) * 3), STAGE_W + 500) - 250;
    art_draw_ex("cloud", cw_v2(x, y + (float)((i * 53) % 90)), cw_v2(300 * scale, 94 * scale), cw_v2(0.5f, 0.5f), 0, cw_rgba(1, 1, 1, alpha), (i & 1) != 0, false);
  }
}
void ui_backdrop(float t, cw_color top, cw_color bottom) {
  ui_grad(cw_rect_make(0, 0, STAGE_W, STAGE_H), top, bottom);
  for (int i = 0; i < 7; i++) { /* slow drifting light pools */
    float x = fmodf((float)i * 233.0f + t * (6 + (float)i * 2), STAGE_W + 400) - 200;
    float y = 80 + (float)((i * 131) % 560);
    art_glow("glow", cw_v2(x, y), 260 + (float)(i % 3) * 120, cw_rgba(top.r + 0.25f, top.g + 0.2f, top.b + 0.35f, 0.12f));
  }
  for (int i = 0; i < 26; i++) { /* twinkling sparkles */
    float x = fmodf((float)i * 97.0f + 40, STAGE_W), y = fmodf((float)i * 61.0f + 17, STAGE_H);
    float k = 0.5f + 0.5f * sinf(t * (1.2f + (float)(i % 5) * 0.4f) + (float)i);
    art_glow("sparkle", cw_v2(x, y), 10 + 16 * k, cw_rgba(1, 1, 1, 0.12f + 0.4f * k * k));
  }
}

/* a chunky logo: candy-coloured letters that bob, with a stack of darker copies under them for depth */
void ui_title(const char *s, cw_vec2 p, float size, float t) {
  float w = ui_text_w(s, size), x = p.x - w * 0.5f;
  char one[2] = { 0, 0 };
  int n = (int)strlen(s);
  for (int pass = 0; pass < 2; pass++) {
    for (int i = 0; i < n; i++) {
      one[0] = s[i];
      char pre[64];
      memcpy(pre, s, (size_t)i);
      pre[i] = '|'; pre[i + 1] = 0;          /* a trailing space is not measured: end the prefix on a bar and subtract it */
      float lx = x + ui_text_w(pre, size) - ui_text_w("|", size);
      float bob = sinf(t * 3.0f + (float)i * 0.6f) * size * 0.04f;
      cw_color c = PCOL[i % 4];
      cw_color top = col_mix(c, cw_rgba(1, 1, 1, 1), 0.35f);
      if (pass == 0) {
        for (int d = 9; d >= 1; d--) cw_r2d_text(pp_font(), one, cw_v2(lx, p.y + bob + (float)d * size * 0.012f), &(cw_text_style){ .size = size, .color = col_mix(c, cw_rgba(0.05f, 0.02f, 0.12f, 1), 0.55f + (float)d * 0.04f), .outline_width = size * 0.07f, .outline_color = cw_rgba(0.05f, 0.02f, 0.12f, 1) });
      } else {
        cw_r2d_text(pp_font(), one, cw_v2(lx, p.y + bob), &(cw_text_style){ .size = size, .color = top, .outline_width = size * 0.05f, .outline_color = cw_rgba(1, 1, 1, 0.9f) });
      }
    }
  }
}
void ui_blob(cw_vec2 p, float r, int player, float lx, float ly, float squash, int mood, bool cpu) {
  static const char *BODY[4] = { "blob_ruby", "blob_sky", "blob_mint", "blob_sun" };
  static const char *FOOT[4] = { "foot_ruby", "foot_sky", "foot_mint", "foot_sun" };
  static const char *HAND[4] = { "hand_ruby", "hand_sky", "hand_mint", "hand_sun" };
  int pl = player & 3;
  float sx = 1 / sqrtf(squash), sy = squash;
  float S = r * 2.36f / 256.0f;           /* sprite pixels to stage units */
  cw_vec2 o = cw_v2(p.x - 128 * S * sx, p.y - 128 * S * sy); /* the sprite's centre sits on p */
#define AT(px, py) cw_v2(o.x + (px) * S * sx, o.y + (py) * S * sy)
  if (!art_is_lit()) art_draw("shadow", cw_v2(p.x, p.y + r * 1.05f), cw_v2(r * 2.1f * sx, r * 0.7f), 0, cw_rgba(1, 1, 1, 0.55f));
  art_draw(FOOT[pl], AT(84, 226), cw_v2(84 * S * sx, 50 * S), 0, (cw_color){ 0 });
  art_draw(FOOT[pl], AT(172, 226), cw_v2(84 * S * sx, 50 * S), 0, (cw_color){ 0 });
  float wave = mood == 1 ? sinf((float)cw_time() * 9 + (float)pl) * 10 : 0;
  art_draw(HAND[pl], AT(8, 150 + wave), cw_v2(46 * S * sx, 46 * S * sy), 0, (cw_color){ 0 });
  art_draw(HAND[pl], AT(248, 150 - wave), cw_v2(46 * S * sx, 46 * S * sy), 0, (cw_color){ 0 });
  art_draw(BODY[pl], p, cw_v2(256 * S * sx, 256 * S * sy), 0, (cw_color){ 0 });
  for (int s = -1; s <= 1; s += 2) {
    cw_vec2 e = AT(128 + s * 36, 112);
    float er = mood == 2 ? 1.12f : 1.0f;
    art_draw("eye", e, cw_v2(50 * S * sx * er, 58 * S * sy * er), 0, (cw_color){ 0 });
    float pr = (mood == 2 ? 20 : 30) * S;
    art_draw("pupil", cw_v2(e.x + lx * 8 * S, e.y + ly * 8 * S), cw_v2(pr * sx, pr * sy), 0, (cw_color){ 0 });
    art_draw("cheek", AT(128 + s * 66, 156), cw_v2(36 * S * sx, 22 * S * sy), 0, cw_rgba(1, 1, 1, 0.55f));
  }
  /* mouth: 0 neutral, 1 happy, 2 shocked, 3 sad */
  cw_vec2 m = AT(128, 160);
  float mr = 14 * S;
  cw_color mc = cw_rgba(0.16f, 0.05f, 0.1f, 1);
  if (mood == 1) { cw_r2d_arc(cw_v2(m.x, m.y - mr * 0.4f), mr * 0.8f, mr * 1.45f, 0.25f, 2.89f, 10, mc); }
  else if (mood == 2) cw_r2d_circle(m, mr * 0.8f, 12, mc);
  else if (mood == 3) cw_r2d_arc(cw_v2(m.x, m.y + mr * 1.6f), mr * 0.8f, mr * 1.45f, 3.39f, 6.03f, 10, mc);
  else cw_r2d_line(cw_v2(m.x - mr, m.y), cw_v2(m.x + mr, m.y), mr * 0.45f, mc);
  if (cpu) { /* a stalk and a lit bead mark a CPU player */
    cw_vec2 b = AT(128, 14);
    cw_r2d_line(b, cw_v2(b.x, b.y - 30 * S), 7 * S, cw_rgba(0.75f, 0.77f, 0.85f, 1));
    art_draw("antenna", cw_v2(b.x, b.y - 42 * S), cw_v2(38 * S, 38 * S), 0, (cw_color){ 0 });
  } else if (pp_hat[pl] > HAT_NONE) ui_hat(AT(128, 22), r * sx, pp_hat[pl], PCOL[pl]);
#undef AT
}

/* ── hats ──────────────────────────────────────────────────────────── */
const char *HAT_NAME[HAT_N] = { "No hat", "Party hat", "Crown", "Top hat", "Flower", "Bow" };
const int HAT_POINTS[HAT_N] = { 0, 4, 8, 12, 16, 20 };
int pp_hat[NP];

static void tri(cw_vec2 a, cw_vec2 b, cw_vec2 c, cw_color col) {
  cw_vertex2d v[3] = { { a, { 0, 0 }, col }, { b, { 0, 0 }, col }, { c, { 0, 0 }, col } };
  static const uint32_t idx[3] = { 0, 1, 2 };
  cw_r2d_triangles((cw_texture){ 0 }, v, 3, idx, 3);
}
void ui_hat(cw_vec2 t, float r, int hat, cw_color tint) {
  float k = r / 30.0f; /* drawn for a blob of radius 30 */
  cw_color dark = cw_rgba(0.12f, 0.08f, 0.16f, 1), gold = cw_rgba(1, 0.8f, 0.22f, 1);
  switch (hat) {
  case HAT_CONE: { /* a striped cone with a pompom, leaning a little */
    cw_vec2 tip = cw_v2(t.x + 4 * k, t.y - 30 * k);
    tri(cw_v2(t.x - 12 * k, t.y + 2 * k), cw_v2(t.x + 12 * k, t.y + 2 * k), tip, col_mix(tint, cw_rgba(1, 1, 1, 1), 0.35f));
    tri(cw_v2(t.x - 6 * k, t.y - 9 * k), cw_v2(t.x + 8 * k, t.y - 9 * k), cw_v2(t.x + 1 * k, t.y - 14 * k), gold);
    cw_r2d_circle(tip, 5 * k, 10, cw_rgba(1, 1, 1, 1));
    break;
  }
  case HAT_CROWN: {
    cw_r2d_rect(cw_rect_make(t.x - 14 * k, t.y - 8 * k, 28 * k, 10 * k), gold);
    for (int i = -1; i <= 1; i++) tri(cw_v2(t.x + (i * 10 - 5) * k, t.y - 7 * k), cw_v2(t.x + (i * 10 + 5) * k, t.y - 7 * k), cw_v2(t.x + i * 10 * k, t.y - (i ? 17 : 21) * k), gold);
    cw_r2d_circle(cw_v2(t.x, t.y - 3 * k), 3 * k, 8, tint);
    break;
  }
  case HAT_TOPHAT:
    cw_r2d_rect(cw_rect_make(t.x - 17 * k, t.y - 3 * k, 34 * k, 5 * k), dark);
    cw_r2d_rect(cw_rect_make(t.x - 11 * k, t.y - 25 * k, 22 * k, 23 * k), dark);
    cw_r2d_rect(cw_rect_make(t.x - 11 * k, t.y - 9 * k, 22 * k, 5 * k), tint);
    break;
  case HAT_FLOWER:
    for (int i = 0; i < 5; i++) { float a = TAU * (float)i / 5; cw_r2d_circle(cw_v2(t.x + 8 * k + cosf(a) * 7 * k, t.y - 6 * k + sinf(a) * 7 * k), 5 * k, 10, cw_rgba(1, 0.95f, 0.98f, 1)); }
    cw_r2d_circle(cw_v2(t.x + 8 * k, t.y - 6 * k), 4.5f * k, 10, gold);
    break;
  case HAT_BOW: {
    cw_color c = col_mix(tint, cw_rgba(1, 0.3f, 0.6f, 1), 0.6f);
    tri(cw_v2(t.x, t.y - 4 * k), cw_v2(t.x - 16 * k, t.y - 13 * k), cw_v2(t.x - 16 * k, t.y + 5 * k), c);
    tri(cw_v2(t.x, t.y - 4 * k), cw_v2(t.x + 16 * k, t.y - 13 * k), cw_v2(t.x + 16 * k, t.y + 5 * k), c);
    cw_r2d_circle(cw_v2(t.x, t.y - 4 * k), 5 * k, 10, col_mix(c, dark, 0.3f));
    break;
  }
  default: break;
  }
}
